func runPlugin(ctx context.Context, path string) ([]byte, error) {
    cmd := exec.CommandContext(ctx, path)
    out, err := cmd.StdoutPipe()
    if err != nil { return nil, err }
    if err := cmd.Start(); err != nil { return nil, err }
    return io.ReadAll(out) // returns here; Wait never called
}

func saveState(dir string, s State) error {
    f, err := os.Create(filepath.Join(dir, "state.json"))
    if err != nil { return err }
    defer f.Close()
    return json.NewEncoder(f).Encode(s) // no fsync, in-place truncate
}
